from claude_agent_sdk import query, ClaudeAgentOptions, AgentDefinition

async for message in query(
    prompt="Review the authentication module for security issues",
    options=ClaudeAgentOptions(
        allowed_tools=["Read", "Grep", "Glob", "Agent"],
        agents={
            "code-reviewer": AgentDefinition(
                description="Code review specialist. Use for quality, security, and maintainability.",
                prompt="""You are a code review specialist. When reviewing code:
- Identify security vulnerabilities
- Verify adherence to standards
- Suggest concrete improvements""",
                tools=["Read", "Grep", "Glob"],
                model="sonnet",
            ),
        },
    ),
):
    if hasattr(message, "result"):
        print(message.result)

async for message in query(prompt="...", options=options):
    # Detect when a subagent is invoked
    if hasattr(message, "content") and message.content:
        for block in message.content:
            # The tool is called "Agent" (older SDK versions used "Task")
            if getattr(block, "type", None) == "tool_use" and block.name in ("Task", "Agent"):
                print(f"Subagent invoked: {block.input.get('subagent_type')}")

    # Detect messages originating FROM within a subagent
    if hasattr(message, "parent_tool_use_id") and message.parent_tool_use_id:
        print("  → (message originated inside the subagent)")

def create_security_agent(level: str) -> AgentDefinition:
    return AgentDefinition(
        description="Specialized security reviewer",
        prompt=f"You are a {'strict (OWASP Top 10 + SANS)' if level == 'strict' else 'balanced'} security reviewer...",
        tools=["Read", "Grep", "Glob"],
        # Opus for strict reviews, Sonnet for regular ones
        model="opus" if level == "strict" else "sonnet",
    )

# Usage:
agents={"security-reviewer": create_security_agent("strict")}
